            if (stor[rects[i].id].length == 0) count++;
            else delete stor[rects[i].id];
            for (uint j = 0; j < rects[i].rects.length; j++) {
                stor[rects[i].id].push(rects[i].rects[j]);
            }
        }
        return count;
    }
}

