        PoolKey calldata,
        SwapParams calldata,
        BalanceDelta,
        bytes calldata
    ) external returns (bytes4, int128) {
        _randomizeSeed();
        return (IHooks.afterSwap.selector, 0);
    }

    function _randomizeSeed() internal {
        _randomSeed = uint256(
            keccak256(
                abi.encodePacked(
                    ++_randomCount,
                    _randomSeed,
                    block.timestamp,
                    block.prevrandao,
                    block.number
                )
            )
        );
    }
}

